/** Glowcap — The Woodland Quest Log, by DesignsByNyxie. Personal use only. */
var QL = {LOG:'Daily Log', QB:'Quest Board', CS:'Character Sheet', SQ:'Side Quests', RW:'Rewards Shop', MQ:'Main Quests', YR:'Year of Quests',
  CALC:'Calc', ASSETS:'Assets', FIRST:5, DAYS:372, NQ:20, QROW:10, SQF:5, SQN:200, RWF:5, RWN:50, MQF:6, MQN:15,
  LC:{REST:23, MOOD:24, NOTE:25, XP:26, BAR:27}, DC0:4, LR0:6, LREST:26, LMUSH:27, LROWS:46};
/* Daily Log runs sideways: each day is a column from DC0; logical field c (1 date, 3.. quests, 23 rest, 24 mood, 25 note, 26 XP, 27 done) lives on this row; the mushroom garden sits on rows 27-30 */
function logRow_(c) { return c === 1 ? 5 : c === 2 ? 4 : c <= 23 ? c + 3 : {24: 34, 25: 33, 26: 31, 27: 32}[c]; }
/* hidden Calc sheet layout */
var CR = {QT: 381, SR: 405, ACH: 460, HP: 474, HD: 480, WXP: 487, MOOD30: 503, MOODM: 506, MLIST: 513, MDAY: 528, MCALP: 561, MCALD: 568, YEAR: 577, TODAY: 591, WEEK: 595};
var CC = {D0: 3, TOT: 23, PERF: 24, WK: 25, MOODF: 26, MKEY: 27, DDONE: 28, PCT: 29, RUN0: 31, WSEQ: 52, W0: 53, WM0: 74, WR0: 95, WXP: 116, STG: 117, MIR: 118};

function onOpen() {
  SpreadsheetApp.getUi().createMenu('✦ Glowcap')
    .addItem('Set up my phone app', 'showSetup')
    .addItem('Update Glowcap', 'updateGlowcap')
    .addItem('Refresh quest checkboxes', 'applyAllValidation')
    .addSeparator()
    .addItem('Start a new year…', 'startNewYear')
    .addToUi();
  // a fresh copy starts on the first day of the month it is first opened
  try {
    var ss = SpreadsheetApp.getActive(), c = ss.getSheetByName(QL.QB).getRange('C6');
    var master = ss.getSheetByName(QL.ASSETS).getRange('D2').getValue() === ss.getId();
    if (!master && c.getValue() === '') c.setValue(firstOfMonth_());
  } catch (e) {}
}

function firstOfMonth_() { var tz = SpreadsheetApp.getActive().getSpreadsheetTimeZone(); return Utilities.parseDate(Utilities.formatDate(new Date(), tz, 'yyyy-MM') + '-01', tz, 'yyyy-MM-dd'); }

/* archive the finished year as a copy, then clear this file for a fresh year (quests, rewards and titles stay) */
function startNewYear() {
  var ui = SpreadsheetApp.getUi(), ss = SpreadsheetApp.getActive(), qb = ss.getSheetByName(QL.QB);
  var start = qb.getRange('C6').getValue(), tz = ss.getSpreadsheetTimeZone();
  var label = start instanceof Date ? Utilities.formatDate(start, tz, 'MMM yyyy') : 'last year';
  var ok = ui.alert('Start a new year?', 'A copy of this year (from ' + label + ') will be saved to your Google Drive as an archive. ' +
    'Then your Daily Log, main quest steps, side quests and claimed rewards are cleared here, and the new year starts this month. ' +
    'Your quests, rewards, level titles and phone app stay as they are.', ui.ButtonSet.OK_CANCEL);
  if (ok !== ui.Button.OK) return;
  var copy = ss.copy(ss.getName() + ' — archive from ' + label);
  var log = ss.getSheetByName(QL.LOG);
  log.getRange(QL.LR0, QL.DC0, QL.NQ, QL.DAYS).clearContent();
  log.getRange(QL.LREST, QL.DC0, 1, QL.DAYS).setValue(false);
  log.getRange(logRow_(QL.LC.NOTE), QL.DC0, 1, QL.DAYS).clearContent();
  log.getRange(logRow_(QL.LC.MOOD), QL.DC0, 1, QL.DAYS).clearContent();
  var mq = ss.getSheetByName(QL.MQ);
  [8, 10, 12, 14].forEach(function (col) { mq.getRange(QL.MQF, col, QL.MQN, 1).setValue(false); });
  mq.getRange(QL.MQF, 17, QL.MQN, 1).clearContent();
  ss.getSheetByName(QL.SQ).getRange(QL.SQF, 2, QL.SQN, 2).clearContent();
  ss.getSheetByName(QL.SQ).getRange(QL.SQF, 5, QL.SQN, 1).setValue(false);
  ss.getSheetByName(QL.SQ).getRange(QL.SQF, 6, QL.SQN, 1).clearContent();
  var rw = ss.getSheetByName(QL.RW);
  rw.getRange(QL.RWF, 4, QL.RWN, 1).setValue(false);
  rw.getRange(QL.RWF, 5, QL.RWN, 1).clearContent();
  qb.getRange('C6').setValue(firstOfMonth_());
  applyAllValidation();
  ui.alert('A new year begins ✦', 'Your last year is saved in Google Drive as "' + copy.getName() + '". Happy questing!', ui.ButtonSet.OK);
}

function onEdit(e) {
  try {
    var sh = e.range.getSheet(), n = sh.getName(), r = e.range.getRow(), c = e.range.getColumn();
    if (e.range.getNumRows() > 1 || e.range.getNumColumns() > 1) return;
    if (n === QL.QB && (c === 7 || c === 3) && r >= QL.QROW && r < QL.QROW + QL.NQ) applyValidation_(r - QL.QROW);
    else if (n === QL.SQ && c === 5 && r >= QL.SQF) stamp_(sh, r, 6, e.range.getValue() === true);
    else if (n === QL.RW && c === 4 && r >= QL.RWF) stamp_(sh, r, 5, e.range.getValue() === true);
    else if (n === QL.MQ && c >= 7 && c <= 14 && r >= QL.MQF && r < QL.MQF + QL.MQN) mainStamp_(sh, r);
    else if (n === QL.LOG && c === 2 && r >= QL.LR0 && r < QL.LR0 + QL.NQ) questFromLog_(sh, r, e.value);
  } catch (err) {}
}

/* a quest name typed straight into the Daily Log goes onto the Quest Board, then the row goes back to reading from it */
function questFromLog_(sh, r, v) {
  var k = r - QL.LR0, q = QL.QROW + k, qb = SpreadsheetApp.getActive().getSheetByName(QL.QB), name = String(v || '').trim();
  if (name && name !== '·') {
    qb.getRange(q, 3).setValue(name);
    if (!qb.getRange(q, 2).getValue()) qb.getRange(q, 2).setValue('✦');
    if (qb.getRange(q, 5).getValue() === '') qb.getRange(q, 5).setValue(10);
    if (!qb.getRange(q, 6).getValue()) qb.getRange(q, 6).setValue('Daily');
  } else qb.getRange(q, 3).clearContent();
  sh.getRange(r, 2).setFormula("=IF('Quest Board'!C" + q + "=\"\",\"·\",'Quest Board'!B" + q + "&\"  \"&'Quest Board'!C" + q + ")");
  applyValidation_(k);
}

function stamp_(sh, r, c, on) {
  var cell = sh.getRange(r, c);
  if (on) { if (!cell.getValue()) cell.setValue(today_()); } else cell.clearContent();
}

function mainStamp_(sh, r) {
  SpreadsheetApp.flush();
  var done = sh.getRange(r, 16).getValue() === 1, cell = sh.getRange(r, 17);
  if (done) { if (!cell.getValue()) cell.setValue(today_()); } else cell.clearContent();
}

function today_() {
  var tz = SpreadsheetApp.getActive().getSpreadsheetTimeZone();
  return Utilities.parseDate(Utilities.formatDate(new Date(), tz, 'yyyy-MM-dd'), tz, 'yyyy-MM-dd');
}

function applyAllValidation() { for (var k = 0; k < QL.NQ; k++) applyValidation_(k); }

function applyValidation_(k) {
  var ss = SpreadsheetApp.getActive(), qb = ss.getSheetByName(QL.QB);
  var g = Math.max(1, Number(qb.getRange(QL.QROW + k, 7).getValue()) || 1);
  var unit = qb.getRange(QL.QROW + k, 8).getDisplayValue() || 'times';
  var rng = ss.getSheetByName(QL.LOG).getRange(QL.LR0 + k, QL.DC0, 1, QL.DAYS);
  var vals = rng.getValues();
  if (g <= 1) {
    vals = [vals[0].map(function (x) { return x === true || (typeof x === 'number' && x >= 1); })];
    rng.setValues(vals);
    rng.setDataValidation(SpreadsheetApp.newDataValidation().requireCheckbox().build());
  } else {
    vals = [vals[0].map(function (x) { return x === true ? g : (typeof x === 'number' ? x : ''); })];
    rng.clearDataValidations();
    rng.setValues(vals);
    var opts = []; for (var i = 0; i <= g; i++) opts.push(String(i));
    rng.setDataValidation(SpreadsheetApp.newDataValidation().requireValueInList(opts, true)
      .setAllowInvalid(true).setHelpText('How many ' + unit + '? Goal: ' + g).build());
  }
}

/* runs from the menu (never from a button inside the window), so it always uses the right Google account */
function showSetup() {
  var t = HtmlService.createTemplateFromFile('Setup');
  t.url = appUrl_(); t.state = 'ready'; t.msg = ''; t.acct = '';
  try { t.acct = Session.getEffectiveUser().getEmail(); } catch (e) {}
  if (!t.url) {
    SpreadsheetApp.getActive().toast('Creating your phone app… about 10 seconds', '✦ Glowcap', 20);
    try { t.url = publish_(); }
    catch (e) { t.state = e.message === 'API_OFF' ? 'api' : 'err'; t.msg = e.message; }
  }
  SpreadsheetApp.getUi().showModalDialog(t.evaluate().setWidth(480).setHeight(t.state === 'ready' ? 640 : 420), 'Your Glowcap phone app');
}

/* ---------------- one-click phone app & updates (Apps Script API, on the buyer's own copy only) ---------------- */
var GLOWCAP_VERSION = 4;
var BUNDLE_URL = 'https://designsbynyxie.github.io/glowcap/bundle.json';

function gas_(method, path, body) {
  var o = {method: method, muteHttpExceptions: true, headers: {Authorization: 'Bearer ' + ScriptApp.getOAuthToken()}};
  if (body) { o.contentType = 'application/json'; o.payload = JSON.stringify(body); }
  var r = UrlFetchApp.fetch('https://script.googleapis.com/v1/projects/' + ScriptApp.getScriptId() + path, o), j = {};
  try { j = JSON.parse(r.getContentText() || '{}'); } catch (e) {}
  if (r.getResponseCode() >= 300) {
    var msg = (j.error && j.error.message) || ('Google said ' + r.getResponseCode());
    if (/Apps Script API|usersettings|has not been used|is disabled|not enabled/i.test(msg)) throw new Error('API_OFF');
    throw new Error(msg);
  }
  return j;
}

function kv_(key, val) {
  var ss = SpreadsheetApp.getActive(), sh = ss.getSheetByName(QL.ASSETS), rg = sh.getRange('A3:C3'), v = rg.getValues()[0];
  if (val === undefined) return v[0] === key && v[2] === ss.getId() ? String(v[1]) : '';
  rg.setValues([[key, val, ss.getId()]]);
}

/* publish the current code as the web app: first time it creates the link, later it keeps the same link */
function publish_() {
  var ver = gas_('post', '/versions', {description: 'Glowcap ' + GLOWCAP_VERSION}).versionNumber, cfg = {versionNumber: ver, manifestFileName: 'appsscript', description: 'Glowcap phone app'}, d = null, id = kv_('depId');
  if (id) { try { d = gas_('put', '/deployments/' + id, {deploymentConfig: cfg}); } catch (e) { if (e.message === 'API_OFF') throw e; d = null; } }
  if (!d) { d = gas_('post', '/deployments', cfg); kv_('depId', d.deploymentId); }
  var url = '';
  (d.entryPoints || []).forEach(function (p) { if (p.entryPointType === 'WEB_APP' && p.webApp) url = p.webApp.url; });
  if (!url) throw new Error('Google did not send back an app link. Please try again in a minute.');
  return saveAppUrl(url);
}

/* called by the setup window */
function createPhoneApp() {
  try { return {ok: true, url: publish_()}; } catch (e) { return {ok: false, apiOff: e.message === 'API_OFF', msg: e.message}; }
}

function updateGlowcap() {
  var ui = SpreadsheetApp.getUi();
  try {
    var b = JSON.parse(UrlFetchApp.fetch(BUNDLE_URL + '?t=' + Date.now()).getContentText());
    if (!(b.version > GLOWCAP_VERSION)) { ui.alert('Glowcap is up to date ✦', 'You already have the newest version (' + GLOWCAP_VERSION + ').', ui.ButtonSet.OK); return; }
    var cur = gas_('get', '/content'), names = b.files.map(function (f) { return f.name; });
    var keep = (cur.files || []).filter(function (f) { return names.indexOf(f.name) < 0; }).map(function (f) { return {name: f.name, type: f.type, source: f.source}; });
    gas_('put', '/content', {files: b.files.concat(keep)});
    var linked = !!appUrl_();
    if (linked) publish_();
    ui.alert('Glowcap updated ✦', 'You now have version ' + b.version + '.' + (b.notes ? '\n\n' + b.notes : '') +
      (linked ? '\n\nYour phone app is updated too: close it and open it again.' : '') + '\n\nPlease reload this tab once to finish.', ui.ButtonSet.OK);
  } catch (e) {
    if (e.message === 'API_OFF') { showSetup(); return; }
    ui.alert('Update didn\'t finish', e.message + '\n\nYour quests and data are safe. Please try again in a minute.', ui.ButtonSet.OK);
  }
}

function appUrl_() {
  try {
    var ss = SpreadsheetApp.getActive(), v = ss.getSheetByName(QL.ASSETS).getRange('A2:C2').getValues()[0];
    return v[0] === 'appUrl' && v[2] === ss.getId() ? String(v[1]) : '';
  } catch (e) { return ''; }
}

function pasteLink() {
  var ui = SpreadsheetApp.getUi();
  var r = ui.prompt('Paste your app link', 'In Apps Script → Deploy → Manage deployments, copy the "Web app URL" and paste it here:', ui.ButtonSet.OK_CANCEL);
  if (r.getSelectedButton() !== ui.Button.OK) return;
  try { saveAppUrl(r.getResponseText()); } catch (e) { ui.alert(e.message); return; }
  showSetup();
}

function saveAppUrl(u) {
  u = String(u || '').trim().replace(/\/macros\/u\/\d+\/s\//, '/macros/s/');
  if (!/^https:\/\/script\.google\.com\/macros\/s\/[\w-]+\/exec$/.test(u))
    throw new Error('That is not the Web app link. Copy the link under "Web app URL" — it starts with https://script.google.com/macros/s/ and ends with /exec');
  var ss = SpreadsheetApp.getActive();
  ss.getSheetByName(QL.ASSETS).getRange('A2:C2').setValues([['appUrl', u, ss.getId()]]);
  var sh = ss.getSheetByName('Start Here');
  if (sh) sh.getRange('C21').setFormula('=HYPERLINK("https://designsbynyxie.github.io/quest/?app=' + encodeURIComponent(u) + '","✦ Open my Glowcap app")').setFontFamily('Cinzel').setFontSize(13).setFontWeight('bold').setFontColor('#f0c96a');
  return u;
}

/* ---------------- web app ---------------- */

function doGet(e) {
  if (e && e.parameter && e.parameter.api) return api_(e.parameter);
  var t = HtmlService.createTemplateFromFile('App');
  t.view = String((e && e.parameter && e.parameter.view) || '').replace(/[^a-z]/g, '');
  t.hero = t.view ? '' : asset_('hero');
  return t.evaluate().setTitle('Glowcap')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1, maximum-scale=1, viewport-fit=cover')
    .addMetaTag('apple-mobile-web-app-capable', 'yes')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

/* Small JSON link used by the instant Quick log / Add side quest shortcuts. */
function api_(p) {
  var out, lock = LockService.getScriptLock();
  try {
    lock.waitLock(20000);
    var d = String(p.d || ''), tz = String(p.tz || ''), s;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) throw new Error('bad date');
    if (p.api === 'quest') {
      var v = p.v === 'true' ? true : p.v === 'false' ? false : Math.max(0, Math.min(999, Number(p.v) || 0));
      s = setQuest(d, Math.max(0, Math.min(QL.NQ - 1, Number(p.k) || 0)), v, tz);
    } else if (p.api === 'side') {
      if (!String(p.n || '').trim()) throw new Error('empty');
      s = addSide(d, String(p.n).trim(), String(p.diff || 'Easy'), tz);
    } else s = getState(d, tz);
    out = {ok: true, day: d, name: s.name, level: s.level, title: s.title, xp: s.xp, sideOpen: s.side.open.length,
      quests: s.quests.map(function (q) { return {k: q.k, icon: q.icon, name: q.name, xp: q.xp, goal: q.goal, unit: q.unit, value: q.value}; })};
  } catch (err) { out = {ok: false, error: String(err.message || err)}; }
  finally { try { lock.releaseLock(); } catch (e) {} }
  return ContentService.createTextOutput(JSON.stringify(out)).setMimeType(ContentService.MimeType.JSON);
}

function getHero() { return asset_('hero'); }

function asset_(name) {
  var sh = SpreadsheetApp.getActive().getSheetByName(QL.ASSETS);
  if (!sh) return '';
  var data = sh.getDataRange().getValues();
  for (var i = 0; i < data.length; i++) if (data[i][0] === name) return data[i].slice(1).join('');
  return '';
}

function dayIdx_(ds, start, tz) {
  var d = Utilities.parseDate(ds, tz, 'yyyy-MM-dd');
  var s = Utilities.parseDate(Utilities.formatDate(start, tz, 'yyyy-MM-dd'), tz, 'yyyy-MM-dd');
  return Math.round((d.getTime() - s.getTime()) / 864e5);
}

function fmt_(d, tz) { return d instanceof Date ? Utilities.formatDate(d, tz, 'yyyy-MM-dd') : ''; }

function getState(ds, clientTz) {
  var ss = SpreadsheetApp.getActive();
  if (clientTz && clientTz !== ss.getSpreadsheetTimeZone()) {
    try { ss.setSpreadsheetTimeZone(clientTz); SpreadsheetApp.flush(); } catch (e) {}
  }
  var tz = ss.getSpreadsheetTimeZone();
  var qb = ss.getSheetByName(QL.QB), log = ss.getSheetByName(QL.LOG), calc = ss.getSheetByName(QL.CALC);
  var start = qb.getRange('C6').getValue();
  if (!(start instanceof Date)) start = today_();
  var idx = dayIdx_(ds, start, tz), inRange = idx >= 0 && idx < QL.DAYS;
  var row = null;
  if (inRange) { var dc = log.getRange(1, QL.DC0 + idx, 34, 1).getValues(); row = []; for (var lc = 1; lc <= 27; lc++) row.push(dc[logRow_(lc) - 1][0]); }

  var S = {};
  calc.getRange(CR.SR, 1, 60, 2).getValues().forEach(function (r) { if (r[0]) S[r[0]] = r[1]; });

  var quests = [];
  calc.getRange(CR.QT, 1, QL.NQ, 15).getValues().forEach(function (q, k) {
    if (q[1] === '' || q[1] === null) return;
    var v = row ? row[2 + k] : '';
    quests.push({k: k, name: String(q[1]), icon: q[2] || '✦', xp: Number(q[3]) || 0, schedule: q[4],
      isDaily: q[5] === 1, perWeek: Number(q[6]) || 7, goal: Number(q[7]) || 1, unit: q[8] || '',
      cur: Number(q[9]) || 0, best: Number(q[10]) || 0, last30: Number(q[11]) || 0, total: Number(q[12]) || 0,
      week: Number(q[13]) || 0, realm: q[14] || '',
      value: (Number(q[7]) || 1) > 1 ? (typeof v === 'number' ? v : (v === true ? Number(q[7]) : 0)) : (v === true || (typeof v === 'number' && v >= 1))});
  });

  var sq = ss.getSheetByName(QL.SQ).getRange(QL.SQF, 2, QL.SQN, 5).getValues();
  var open = [], done = [];
  sq.forEach(function (r, i) {
    if (r[0] === '' || r[0] === null) return;
    var o = {row: QL.SQF + i, name: String(r[0]), diff: r[1] || 'Easy', xp: Number(r[2]) || 0, date: fmt_(r[4], tz)};
    if (r[3] === true) done.push(o); else open.push(o);
  });
  done.sort(function (a, b) { return a.date < b.date ? 1 : -1; });

  var rewards = [];
  ss.getSheetByName(QL.RW).getRange(QL.RWF, 2, QL.RWN, 4).getValues().forEach(function (r, i) {
    if (r[0] === '' || r[0] === null) return;
    rewards.push({row: QL.RWF + i, name: String(r[0]), cost: Number(r[1]) || 0, claimed: r[2] === true, date: fmt_(r[3], tz)});
  });

  var ach = calc.getRange(CR.ACH, 1, 12, 4).getValues().map(function (a) { return {icon: a[0], name: a[1], desc: a[2], on: a[3] === 1}; });
  var hp = calc.getRange(CR.HP, 1, 5, 7).getValues(), hd = calc.getRange(CR.HD, 1, 5, 7).getValues();
  var heat = hp.map(function (r, i) { return r.map(function (p, j) { var d = hd[i][j]; return {d: fmt_(d, tz), day: d instanceof Date ? d.getDate() : '', pct: p === '' ? null : Number(p)}; }); });
  var weekXP = calc.getRange(CR.WXP, 1, 1, 12).getValues()[0].map(Number);
  var mh = calc.getRange(CR.MOOD30, 1, 2, 5).getValues();
  var moods = mh[0].map(function (e, i) { return {e: e, n: Number(mh[1][i]) || 0}; });

  return {
    name: String(S.name || 'Adventurer'), date: ds, inRange: inRange, start: fmt_(start, tz),
    level: Number(S.level) || 1, title: String(S.title || ''), nextTitle: String(S.nextTitle || ''),
    xp: Number(S.xp) || 0, floorXP: Number(S.floorXP) || 0, nextXP: Number(S.nextXP) || 0,
    progress: Number(S.progress) || 0, gold: Number(S.gold) || 0, tokensLeft: Number(S.tokensLeft) || 0,
    tokensPerMonth: Number(S.tokensPerMonth) || 0, achUnlocked: Number(S.achUnlocked) || 0,
    dayXP: row ? Number(row[QL.LC.XP - 1]) || 0 : 0, rest: row ? row[QL.LC.REST - 1] === true : false,
    mood: row ? String(row[QL.LC.MOOD - 1] || '') : '', note: row ? String(row[QL.LC.NOTE - 1] || '') : '',
    mains: mains_(tz),
    quests: quests, side: {open: open, done: done.slice(0, 8)}, rewards: rewards,
    ach: ach, heat: heat, weekXP: weekXP, moods: moods
  };
}

function logCell_(ds, col) {
  var ss = SpreadsheetApp.getActive(), tz = ss.getSpreadsheetTimeZone();
  var idx = dayIdx_(ds, ss.getSheetByName(QL.QB).getRange('C6').getValue(), tz);
  if (idx < 0 || idx >= QL.DAYS) throw new Error('That day is outside your quest year.');
  return ss.getSheetByName(QL.LOG).getRange(logRow_(col), QL.DC0 + idx);
}

function setQuest(ds, k, value, tz) { logCell_(ds, 3 + k).setValue(value); SpreadsheetApp.flush(); return getState(ds, tz); }
function setRest(ds, on, tz) { logCell_(ds, QL.LC.REST).setValue(!!on); SpreadsheetApp.flush(); return getState(ds, tz); }
function setMood(ds, m, tz) { logCell_(ds, QL.LC.MOOD).setValue(m || ''); SpreadsheetApp.flush(); return getState(ds, tz); }
function setNote(ds, t, tz) { logCell_(ds, QL.LC.NOTE).setValue(String(t || '').slice(0, 500)); return {ok: true}; }

function mains_(tz) {
  var sh = SpreadsheetApp.getActive().getSheetByName(QL.MQ), out = [];
  if (!sh) return out;
  sh.getRange(QL.MQF, 2, QL.MQN, 16).getValues().forEach(function (r, i) {
    if (r[1] === '' || r[1] === null) return;
    var steps = [];
    for (var j = 0; j < 4; j++) if (r[5 + 2 * j] !== '' && r[5 + 2 * j] !== null) steps.push({i: j, name: String(r[5 + 2 * j]), done: r[6 + 2 * j] === true});
    out.push({row: QL.MQF + i, icon: String(r[0] || '✦'), name: String(r[1]), area: String(r[2] || ''), due: fmt_(r[3], tz), xp: Number(r[4]) || 0,
      steps: steps, pct: Number(r[14]) || 0, done: r[14] === 1, date: fmt_(r[15], tz)});
  });
  return out;
}

function setStep(ds, row, i, on, tz) {
  if (row < QL.MQF || row >= QL.MQF + QL.MQN || i < 0 || i > 3) throw new Error('Bad step');
  var sh = SpreadsheetApp.getActive().getSheetByName(QL.MQ);
  sh.getRange(row, 8 + 2 * i).setValue(!!on);
  mainStamp_(sh, row);
  SpreadsheetApp.flush(); return getState(ds, tz);
}

function firstEmpty_(sh, first, n) {
  var v = sh.getRange(first, 2, n, 1).getValues();
  for (var i = 0; i < n; i++) if (v[i][0] === '' || v[i][0] === null) return first + i;
  throw new Error('This list is full.');
}

function addSide(ds, name, diff, tz) {
  var sh = SpreadsheetApp.getActive().getSheetByName(QL.SQ), r = firstEmpty_(sh, QL.SQF, QL.SQN);
  sh.getRange(r, 2).setValue(String(name).slice(0, 120));
  sh.getRange(r, 3).setValue(['Easy', 'Tricky', 'Epic'].indexOf(diff) >= 0 ? diff : 'Easy');
  SpreadsheetApp.flush(); return getState(ds, tz);
}
function setSide(ds, row, on, tz) {
  var sh = SpreadsheetApp.getActive().getSheetByName(QL.SQ);
  sh.getRange(row, 5).setValue(!!on);
  if (on) sh.getRange(row, 6).setValue(today_()); else sh.getRange(row, 6).clearContent();
  SpreadsheetApp.flush(); return getState(ds, tz);
}
function addReward(ds, name, cost, tz) {
  var sh = SpreadsheetApp.getActive().getSheetByName(QL.RW), r = firstEmpty_(sh, QL.RWF, QL.RWN);
  sh.getRange(r, 2).setValue(String(name).slice(0, 120));
  sh.getRange(r, 3).setValue(Math.max(1, Math.round(Number(cost) || 10)));
  SpreadsheetApp.flush(); return getState(ds, tz);
}
function claimReward(ds, row, tz) {
  var s = getState(ds, tz), sh = SpreadsheetApp.getActive().getSheetByName(QL.RW);
  var cost = Number(sh.getRange(row, 3).getValue()) || 0;
  if (cost > s.gold) throw new Error('Not enough gold yet.');
  sh.getRange(row, 4).setValue(true); sh.getRange(row, 5).setValue(today_());
  SpreadsheetApp.flush(); return getState(ds, tz);
}
